import re
from datetime import datetime


def dedupe_contacts(rows):
    """Normalize, deduplicate, and merge CRM contact rows."""

    def normalize_email(value):
        value = value or ""
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")

        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        value = value or ""
        marker = re.search(r"(?:ext|x|#)", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = (value or "").strip()
        if "-" in value:
            value = value.split("-", 1)[0]

        if len(value) == 4 and value.isdigit():
            value = "0" + value

        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = (value or "").strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        for fmt in ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated date: {value!r}")

    def normalize_opted_out(value):
        return (value or "").strip().lower() in {"y", "yes", "true", "1"}

    def normalize_tags(value):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value or "")
            if tag.strip()
        }

    records = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))

        # Drop rows without either a valid email or a valid phone.
        if not email and not phone:
            continue

        records.append({
            "input_index": input_index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "tags": normalize_tags(row.get("tags", "")),
            "opted_out": normalize_opted_out(row.get("opted_out", "")),
            "updated": parse_updated(row["updated"]),
            "source": (row.get("source", "") or "").strip().lower(),
        })

    # Disjoint-set union tracks transitive matches.
    parent = list(range(len(records)))
    rank = [0] * len(records)

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(left, right):
        left_root = find(left)
        right_root = find(right)

        if left_root == right_root:
            return

        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root

        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1

    email_owner = {}
    phone_last_name_owner = {}

    for index, record in enumerate(records):
        if record["email"]:
            previous = email_owner.get(record["email"])
            if previous is None:
                email_owner[record["email"]] = index
            else:
                union(index, previous)

        if record["phone"] and record["last_name"]:
            key = (record["phone"], record["last_name"].casefold())
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index in range(len(records)):
        groups.setdefault(find(index), []).append(index)

    def pick_field(group_indices, field):
        candidates = [
            records[index]
            for index in group_indices
            if records[index][field] != ""
        ]
        if not candidates:
            return ""

        chosen = max(
            candidates,
            key=lambda record: (
                record["source"] == "manual",
                record["updated"],
                -record["input_index"],
            ),
        )
        return chosen[field]

    output = []

    for group_indices in groups.values():
        group_indices.sort(key=lambda index: records[index]["input_index"])
        group_records = [records[index] for index in group_indices]

        tags = set()
        for record in group_records:
            tags.update(record["tags"])

        latest_updated = max(record["updated"] for record in group_records)

        output.append({
            "first_name": pick_field(group_indices, "first_name"),
            "last_name": pick_field(group_indices, "last_name"),
            "zip": pick_field(group_indices, "zip"),
            "email": pick_field(group_indices, "email"),
            "phone": pick_field(group_indices, "phone"),
            "source": pick_field(group_indices, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": (
                "Y" if any(record["opted_out"] for record in group_records)
                else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
            "_earliest_index": group_records[0]["input_index"],
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
